parameters.new_string:
// Start a goroutine to close the results channel once all workers are done
// and to drain the results.
var resultsWg sync.WaitGroup
resultsWg.Add(1)
go func() {
	defer resultsWg.Done()
	for range results {
		// Just drain
	}
}()

// Wait for all workers to finish
wg.Wait()
close(results) // All workers are done, no more results will be sent

resultsWg.Wait() // Wait for the results to be fully consumed and closed

